body.script:
(function () {
    "use strict";
    var script = document.getElementById("o_sign_script");
    var contentUrl = script.dataset.contentUrl;
    var stage = document.getElementById("o_sign_stage");
    var message = document.getElementById("o_sign_message");
    var offline = document.getElementById("o_sign_offline");
    var digest = null, reload = null, size = null, timer = null;
    var cacheKey = "o_inventory_sign:" + contentUrl;

    function pad(n) { return (n < 10 ? "0" : "") + n; }
    function tick() {
        var now = new Date();
        var date = pad(now.getDate()) + "/" + pad(now.getMonth() + 1) + "/" + now.getFullYear();
        var time = pad(now.getHours()) + ":" + pad(now.getMinutes());
        document.querySelectorAll("[data-clock]").forEach(function (el) {
            var fmt = el.dataset.clock;
            el.textContent = fmt === "date" ? date : fmt === "datetime" ? date + " " + time : time;
        });
    }
    function fit() {
        if (!size) { return; }
        var scale = Math.min(window.innerWidth / size[0], window.innerHeight / size[1]);
        stage.style.transform = "scale(" + scale + ")";
        stage.style.left = Math.max((window.innerWidth - size[0] * scale) / 2, 0) + "px";
        stage.style.top = Math.max((window.innerHeight - size[1] * scale) / 2, 0) + "px";
    }
    function show(data) {
        if (data.reload !== undefined) {
            if (reload !== null && data.reload !== reload) { window.location.reload(); return; }
            reload = data.reload;
        }
        document.title = data.name || document.title;
        document.body.style.background = data.background || "#FFFFFF";
        if (data.digest !== digest) {
            digest = data.digest;
            size = [data.width, data.height];
            stage.style.width = data.width + "px";
            stage.style.height = data.height + "px";
            stage.innerHTML = data.html;
            message.style.display = "none";
            fit();
            tick();
        }
    }
    function schedule(seconds) {
        clearTimeout(timer);
        timer = setTimeout(load, Math.max(seconds || 60, 10) * 1000);
    }
    function load() {
        var url = contentUrl + (contentUrl.indexOf("?") < 0 ? "?" : "&") +
            "w=" + window.screen.width + "&h=" + window.screen.height;
        fetch(url, { credentials: "same-origin", cache: "no-store" })
            .then(function (response) {
                if (response.status === 401 || response.status === 403) {
                    throw new Error("auth");
                }
                return response.json();
            })
            .then(function (data) {
                if (data.status === "error") { throw new Error(data.message); }
                offline.style.display = "none";
                try { localStorage.setItem(cacheKey, JSON.stringify(data)); } catch (e) { /* storage full or blocked */ }
                show(data);
                schedule(data.refresh);
            })
            .catch(function (error) {
                var saved = null;
                try { saved = JSON.parse(localStorage.getItem(cacheKey) || "null"); } catch (e) { saved = null; }
                if (saved && digest === null) { show(saved); }
                if (digest !== null) {
                    offline.style.display = "block";
                } else {
                    message.textContent = error.message === "auth"
                        ? "Log in to Odoo on this screen to show the sign."
                        : "Waiting for the sign… (" + error.message + ")";
                }
                schedule(30);
            });
    }
    window.addEventListener("resize", fit);
    setInterval(tick, 1000);
    if (script.dataset.pwa && "serviceWorker" in navigator) {
        navigator.serviceWorker.register("/inventory/signage/sw.js", { scope: "/inventory/signage/" })
            .catch(function () { /* the sign works without it */ });
    }
    load();
})();

(function () {
    "use strict";
    var prompt = null;
    var button = document.getElementById("o_install");
    window.addEventListener("beforeinstallprompt", function (ev) {
        ev.preventDefault();
        prompt = ev;
        button.style.display = "inline-block";
    });
    button.addEventListener("click", function () {
        if (prompt) { prompt.prompt(); prompt = null; button.style.display = "none"; }
    });
    if ("serviceWorker" in navigator) {
        navigator.serviceWorker.register("/inventory/signage/sw.js", { scope: "/inventory/signage/" })
            .catch(function () { /* the picker works without it */ });
    }
})();
